/*
  # Swimming Programs - All Objectives

  Populates weekly structures for 12 swimming programs (3 per objective)
*/

-- SWIMMING BASE #2-4
UPDATE program_templates SET weekly_structure = '[
  {"week_number": 1, "focus": "Foundation", "sessions": [{"day": 2, "workout_name": "Aerobic 400s 5x400m Easy", "description": "Aerobic base", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "1000m Easy Swim (30 min)", "description": "Easy swim", "duration_minutes": 30, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Swim 3000m", "description": "Long swim", "duration_minutes": 70, "intensity": "easy"}]},
  {"week_number": 2, "focus": "Volume", "sessions": [{"day": 2, "workout_name": "Aerobic 400s 5x400m Easy", "description": "Aerobic", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "Aerobic Descend 5x400 m (Negative Split)", "description": "Descending", "duration_minutes": 60, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Swim 3000m", "description": "Long", "duration_minutes": 70, "intensity": "easy"}]},
  {"week_number": 3, "focus": "Progression", "sessions": [{"day": 2, "workout_name": "Aerobic Volume 6x400 m with Rest", "description": "Volume", "duration_minutes": 65, "intensity": "easy"},{"day": 4, "workout_name": "1000m Easy Swim (30 min)", "description": "Easy", "duration_minutes": 30, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Endurance 5000m Block", "description": "Long swim", "duration_minutes": 90, "intensity": "moderate"}]},
  {"week_number": 4, "focus": "Recovery", "sessions": [{"day": 2, "workout_name": "1000m Easy Swim (30 min)", "description": "Easy", "duration_minutes": 30, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic 400s 5x400m Easy", "description": "Light", "duration_minutes": 60, "intensity": "easy"}]},
  {"week_number": 5, "focus": "Build", "sessions": [{"day": 2, "workout_name": "Aerobic Volume 6x400 m with Rest", "description": "Volume", "duration_minutes": 65, "intensity": "easy"},{"day": 4, "workout_name": "Aerobic Descend 5x400 m (Negative Split)", "description": "Descending", "duration_minutes": 60, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Swim 3000m", "description": "Long", "duration_minutes": 70, "intensity": "easy"}]},
  {"week_number": 6, "focus": "Peak", "sessions": [{"day": 2, "workout_name": "Aerobic 400s 5x400m Easy", "description": "Aerobic", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "Aerobic Volume 6x400 m with Rest", "description": "Volume", "duration_minutes": 65, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Endurance 5000m Block", "description": "Peak swim", "duration_minutes": 90, "intensity": "moderate"}]},
  {"week_number": 7, "focus": "Consolidation", "sessions": [{"day": 2, "workout_name": "Aerobic Descend 5x400 m (Negative Split)", "description": "Descending", "duration_minutes": 60, "intensity": "easy"},{"day": 4, "workout_name": "1000m Easy Swim (30 min)", "description": "Easy", "duration_minutes": 30, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Long Swim 3000m", "description": "Long", "duration_minutes": 70, "intensity": "easy"}]},
  {"week_number": 8, "focus": "Test", "sessions": [{"day": 2, "workout_name": "1000m Easy Swim (30 min)", "description": "Taper", "duration_minutes": 30, "intensity": "easy"},{"day": 6, "workout_name": "1000m Straight Swim — Stroke Count Test", "description": "Assessment", "duration_minutes": 35, "intensity": "moderate"}]}
]'::jsonb WHERE name IN ('Open Water Base', 'Pool Endurance', 'Technique & Endurance') AND discipline = 'swimming';

